#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(Seurat);library(SeuratObject)})
root<-normalizePath(file.path(getwd(),"subtype"),mustWork=TRUE);r4<-file.path(root,"round4_final");source(file.path(r4,"code","00_round4_config.R"))
audit<-read.csv(file.path(r4,"00_input_audit","round4_input_object_audit.csv"),stringsAsFactors=FALSE);pathof<-setNames(audit$object_path,audit$object)
lineages<-c("Fibroblast","Mural","TNK");newobjs<-list();oldobjs<-list()
for(n in lineages){oldobjs[[n]]<-qs2::qs_read(pathof[[n]]);newobjs[[n]]<-qs2::qs_read(file.path(r4,"02_reclustering",n,paste0(n,"_round4_final_preannotation.qs2")))}
for(n in lineages){old<-oldobjs[[n]][[]];new<-newobjs[[n]][[]];shared<-intersect(rownames(old),rownames(new));for(rr in round4_config$resolutions){z<-as.data.frame(table(round3_cluster=old[shared,"round3_res_1.2"],round4_cluster=new[shared,round4_res_field(rr)]),stringsAsFactors=FALSE);names(z)[3]<-"n_cells";z<-z[z$n_cells>0,,drop=FALSE];z$fraction_of_round3_cluster<-ave(z$n_cells,z$round3_cluster,FUN=function(x)x/sum(x));write.csv(z,file.path(r4,"03_transition_audit",paste0(n,"_R3_to_R4_res",rr,"_transition.csv")),row.names=FALSE)}}
special<-list(Fibro_C11_after_move_to_Mural=list(source="Fibroblast",cluster="11",dest="Mural"),Fibro_C19_after_move_to_Mural=list(source="Fibroblast",cluster="19",dest="Mural"),Mural_C4_after_move_to_Fibro=list(source="Mural",cluster="4",dest="Fibroblast"),Mural_C15_after_move_to_Fibro=list(source="Mural",cluster="15",dest="Fibroblast"))
for(nm in names(special)){s<-special[[nm]];old<-oldobjs[[s$source]][[]];cells<-rownames(old)[as.character(old$round3_res_1.2)==s$cluster];new<-newobjs[[s$dest]][[]];if(!all(cells%in%rownames(new)))stop("Moved cells absent: ",nm);z<-as.data.frame(table(round4_cluster=new[cells,"round4_res_1.2"]),stringsAsFactors=FALSE);names(z)[2]<-"n_cells";z<-z[z$n_cells>0,,drop=FALSE];z$round3_source=s$source;z$round3_cluster=s$cluster;z$round4_destination=s$dest;z$fraction_of_moved_population=z$n_cells/length(cells);write.csv(z,file.path(r4,"03_transition_audit",paste0(nm,"_transition.csv")),row.names=FALSE)}
for(n in lineages){obj<-newobjs[[n]];for(rr in round4_config$resolutions){field<-round4_res_field(rr);sizes<-as.data.frame(table(cluster=obj[[field,drop=TRUE]]),stringsAsFactors=FALSE);names(sizes)[2]<-"n_cells";top<-read.csv(file.path(r4,"02_reclustering",n,"tables",paste0("Round4_markers_res",rr,"_top50_annotation_friendly.csv")),stringsAsFactors=FALSE);fc<-intersect(c("avg_log2FC","avg_logFC"),names(top))[1];top<-top[order(as.character(top$cluster),-top[[fc]]),,drop=FALSE];genes<-tapply(top$gene,as.character(top$cluster),function(x)paste(head(x,10),collapse=";"));templ<-data.frame(cluster=as.character(sizes$cluster),n_cells=sizes$n_cells,top10_markers=unname(genes[as.character(sizes$cluster)]),proposed_annotation="",confidence="",notes="",stringsAsFactors=FALSE);prefix<-if(n=="Fibroblast")"Fibro"else n;write.csv(templ,file.path(r4,"04_final_annotation_support",paste0(prefix,"_res",rr,"_annotation_table_template.csv")),row.names=FALSE)}}
acct<-read.csv(file.path(r4,"05_summary","round4_lineage_correction_accounting.csv"));rows<-list()
for(n in lineages){s<-read.csv(file.path(r4,"02_reclustering",n,"tables","round4_object_summary.csv"));a<-acct[acct$lineage==n,];rows[[n]]<-data.frame(lineage=n,round3_n_cells=a$round3_cells,n_moved_in=a$moved_in,n_moved_out=a$moved_out,n_excluded=a$excluded,round4_n_cells=s$round4_n_cells,Harmony_variable=s$Harmony_variable,PCA_dims=s$PCA_dims,neighbor_dims=s$neighbor_dims,n_clusters_res0.4=s$n_clusters_res0.4,n_clusters_res1.2=s$n_clusters_res1.2,smallest_cluster_res0.4=s$smallest_cluster_res0.4,smallest_cluster_res1.2=s$smallest_cluster_res1.2,status=s$status)}
for(n in c("Myeloid","Endothelial","Schwann")){a<-audit[audit$object==n,];rows[[n]]<-data.frame(lineage=n,round3_n_cells=a$n_cells,n_moved_in=0,n_moved_out=0,n_excluded=0,round4_n_cells=a$n_cells,Harmony_variable=NA,PCA_dims=NA,neighbor_dims=NA,n_clusters_res0.4=NA,n_clusters_res1.2=NA,smallest_cluster_res0.4=NA,smallest_cluster_res1.2=NA,status="FROZEN_FROM_ROUND3")}
summary<-do.call(rbind,rows);write.csv(summary,file.path(r4,"05_summary","round4_final_summary.csv"),row.names=FALSE)
valid<-list();for(n in lineages){o<-newobjs[[n]];base<-file.path(r4,"02_reclustering",n);m<-o[[]];markers<-all(file.exists(unlist(lapply(round4_config$resolutions,function(rr)file.path(base,"tables",paste0("Round4_markers_res",rr,c("_full.csv","_top50_raw.csv","_top50_annotation_friendly.csv","_top50_non_cellcycle.csv")))))));plots<-all(file.exists(unlist(lapply(round4_config$resolutions,function(rr)c(file.path(base,"figures",paste0("Round4_",n,"_UMAP_res",rr,c(".pdf",".png"))),file.path(base,"figures",paste0("Round4_",n,"_canonical_DotPlot_res",rr,c(".pdf",".png"))))))));valid[[n]]<-data.frame(lineage=n,n_cells=ncol(o),reductions_ok=all(c("round4_pca","round4_harmony","round4_umap")%in%Reductions(o)),resolution_fields_ok=all(round4_res_field(round4_config$resolutions)%in%names(m)),no_forbidden_resolutions=!any(grepl("^round4_res_(0[.]2|0[.]6|0[.]8|1[.]0|1[.]5)$",names(m))),harmony_ok=all(o$round4_harmony_variable=="orig.ident"),no_final_annotation=!any(c("fine_celltype","final_celltype","cell_state")%in%names(m)),marker_files_ok=markers,plot_files_ok=plots)}
v<-do.call(rbind,valid);write.csv(v,file.path(r4,"05_summary","round4_output_validation.csv"),row.names=FALSE);if(!all(unlist(v[,-c(1,2)])))stop("Output validation failed")
p<-read.csv(file.path(r4,"05_summary","final_reference_cell_provenance.csv"),stringsAsFactors=FALSE);if(anyDuplicated(p$cell_barcode)||anyNA(p$round4_action)||anyNA(p$round4_destination))stop("Provenance failed")
cat("ROUND4_FINAL COMPLETE\n\nFIBRO C11 -> MURAL\nFIBRO C19 -> MURAL\nFIBRO C9 KEPT IN FIBRO\n\nMURAL C4 -> FIBRO\nMURAL C15 -> FIBRO\n\nTNK C5 REMOVED FROM REFERENCE\nTNK C16 REMOVED FROM REFERENCE\nTNK SINGLETON REMOVED IF PRESENT\n\nMYELOID FROZEN FROM ROUND3\nENDOTHELIAL FROZEN FROM ROUND3\nSCHWANN FROZEN FROM ROUND3\n\nMT-HIGH / CYCLING / IFN / ACTIVATED STATES WERE NOT REMOVED\n\nONLY RESOLUTIONS 0.4 AND 1.2 WERE RUN\n\nNO LOCAL RESCUE\nNO RESOLUTION 0.8\nNO AUTOMATIC FINAL ANNOTATION\n\nROUND4_FINAL IS THE LAST RECLUSTERING ROUND\n\nSTOPPED BEFORE MANUAL FINAL ANNOTATION AND SPATIAL REFERENCE CONSTRUCTION\n")
